const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
const j = item.json || {};
let usable = true, problem = '', field = '', mime = '', fileName = '', sizeMb = 0;

if (keys.length === 0) {
  usable = false; problem = 'No file came through with the form. Please upload the recording again.';
} else {
  field = keys[0];
  const meta = bin[field] || {};
  mime = String(meta.mimeType || '');
  fileName = String(meta.fileName || 'recording');
  const rawSize = String(meta.fileSize || '');
  const n = parseFloat(rawSize.replace(/[^0-9.]/g, '')) || 0;
  sizeMb = /kb/i.test(rawSize) ? n / 1024 : (/gb/i.test(rawSize) ? n * 1024 : n);
  if (mime.indexOf('video/') !== 0) {
    usable = false; problem = 'That file looks like ' + (mime || 'an unknown type') + ' rather than a video. Upload an MP4, MOV or WebM screen recording.';
  } else if (sizeMb > 0 && sizeMb < 0.05) {
    usable = false; problem = 'The recording is only ' + sizeMb.toFixed(2) + ' MB, too short to contain a process. Record the whole task from start to finish.';
  } else if (sizeMb > 300) {
    usable = false; problem = 'The recording is ' + Math.round(sizeMb) + ' MB. Trim it to the task itself, or split a long process into separate recordings.';
  }
}

return [{ json: {
  usable: usable, problem: problem, binaryField: field, fileName: fileName, sizeMb: Math.round(sizeMb * 10) / 10,
  processName: j['What is this process called'] || 'Untitled process',
  audience: j['Who will follow it'] || 'a new team member',
  criticality: j['How critical is it'] || 'Routine'
}, binary: item.binary }];

const src = $('Check the Recording').first();
const meta = src.json;
let parsed = {};
try {
  const raw = String($json.content || $json.text || '').replace(/```json|```/g, '').trim();
  parsed = raw ? JSON.parse(raw) : {};
} catch (e) { parsed = {}; }

const mmss = function (sec) {
  const s = Math.max(0, Math.round(Number(sec) || 0));
  const m = Math.floor(s / 60), r = s % 60;
  return (m < 10 ? '0' : '') + m + ':' + (r < 10 ? '0' : '') + r;
};

const steps = [];
for (const s of (Array.isArray(parsed.steps) ? parsed.steps : [])) {
  const doText = String(s.do || '').trim();
  if (!doText) continue;
  steps.push({
    n: steps.length + 1, tSec: Number(s.t) || 0, at: mmss(s.t), doText: doText,
    where: String(s.where || '').trim(), watch: String(s.watch || '').trim(),
    sure: s.sure !== false, ask: String(s.ask || '').trim(), verified: false
  });
}

const state = { processName: meta.processName, audience: meta.audience, criticality: meta.criticality, binaryField: meta.binaryField, steps: steps, toolsUsed: Array.isArray(parsed.tools_used) ? parsed.tools_used.join(', ') : '', outcome: String(parsed.outcome || ''), recordingQuality: String(parsed.recording_quality || 'clear'), quality_note: String(parsed.quality_note || '') };

const MAX_RECHECKS = 4;
const unsure = steps.filter(function (s) { return !s.sure; }).slice(0, MAX_RECHECKS);

if (unsure.length === 0) {
  return [{ json: Object.assign({ nothingToRecheck: true, recheckCount: 0 }, state) }];
}

return unsure.map(function (s) {
  return { json: Object.assign({ nothingToRecheck: false, recheckCount: unsure.length, stepNo: s.n, at: s.at, tSec: s.tSec, ask: s.ask || ('What exactly happens at ' + s.at + '?') }, state), binary: src.binary };
});

const base = $('Find the Weak Points').first().json;
const steps = JSON.parse(JSON.stringify(base.steps || []));

let answers = [];
let asked = [];
try { answers = $('Look Again at That Moment').all().map(function (i) { return i.json; }); } catch (e) { answers = []; }
try { asked = $('Loop Over Uncertain Moments').all().map(function (i) { return i.json; }); } catch (e) { asked = []; }

let verified = 0, stillUnclear = 0;
for (let i = 0; i < answers.length; i++) {
  const target = asked[i] || {};
  let a = {};
  try {
    const raw = String(answers[i].content || answers[i].text || '').replace(/```json|```/g, '').trim();
    a = raw ? JSON.parse(raw) : {};
  } catch (e) { a = {}; }

  const idx = steps.findIndex(function (s) { return s.n === target.stepNo; });
  if (idx === -1) continue;

  if (a.answered === true && String(a.do || '').trim()) {
    steps[idx].doText = String(a.do).trim();
    steps[idx].where = String(a.where || steps[idx].where).trim();
    steps[idx].watch = String(a.watch || steps[idx].watch).trim();
    steps[idx].verified = true;
    steps[idx].sure = true;
    verified++;
  } else {
    steps[idx].watch = (steps[idx].watch ? steps[idx].watch + ' ' : '') + 'Could not be read from the recording' + (a.note ? ': ' + a.note : '') + '.';
    stillUnclear++;
  }
}

const unresolved = steps.filter(function (s) { return !s.sure; }).length;

return [{ json: Object.assign({}, base, {
  steps: steps,
  stepCount: steps.length,
  recheckedCount: answers.length,
  verifiedCount: verified,
  stillUnclearCount: stillUnclear + unresolved,
  stepsText: steps.map(function (s) { return s.n + '. [' + s.at + '] ' + s.doText + (s.where ? ' (' + s.where + ')' : '') + (s.sure ? '' : ' <-- still unclear'); }).join('\n')
}) }];

const src = $('Patch In What We Verified').first().json;
const g = $json.output || {};
const rows = [];
const src2 = function (s) { return s.verified ? 'Confirmed on a second viewing' : (s.sure ? 'Shown on the recording' : 'UNREADABLE - confirm before use'); };

for (const s of src.steps) rows.push({ 'Step': s.n, 'Timestamp': s.at, 'What to do': s.doText, 'Where': s.where, 'Watch out for': s.watch, 'Source': src2(s) });

const block = function (title, arr, why) {
  if (!Array.isArray(arr) || arr.length === 0) return;
  rows.push({ 'Step': '', 'Timestamp': '', 'What to do': title, 'Where': '', 'Watch out for': '', 'Source': '' });
  for (const x of arr) rows.push({ 'Step': '', 'Timestamp': '', 'What to do': String(x), 'Where': '', 'Watch out for': why, 'Source': 'NOT shown - confirm before use' });
};

rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'VERIFY BEFORE THIS PROCEDURE IS USED', 'Where': '', 'Watch out for': 'Score ' + (g.completeness_score || 0) + '/100. ' + (g.verdict || ''), 'Source': '' });
block('Prerequisites never demonstrated', g.missing_prerequisites, 'Confirm with the process owner');
block('Failure paths never demonstrated', g.undemonstrated_failures, 'Add a step for this case');
block('Judgement calls the recording assumed', g.tacit_knowledge, 'Write down the rule being applied');
block('Risky or irreversible steps', g.risky_steps, 'Consider an approval or a check');

if (Array.isArray(g.quiz) && g.quiz.length) {
  rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'CHECK OF UNDERSTANDING', 'Where': '', 'Watch out for': '', 'Source': '' });
  for (let i = 0; i < g.quiz.length; i++) rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'Q' + (i + 1) + '. ' + (g.quiz[i].question || ''), 'Where': '', 'Watch out for': 'Expected: ' + (g.quiz[i].answer || ''), 'Source': 'Training check' });
}

return rows.map(function (r) { return { json: r }; });

const src = $('Patch In What We Verified').first().json;
const g = $json.output || {};
const rows = [];
const src2 = function (s) { return s.verified ? 'Confirmed on a second viewing' : 'Shown on the recording'; };

for (const s of src.steps) rows.push({ 'Step': s.n, 'Timestamp': s.at, 'What to do': s.doText, 'Where': s.where, 'Watch out for': s.watch, 'Source': src2(s) });

if (Array.isArray(g.risky_steps) && g.risky_steps.length) {
  rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'BEFORE YOU START', 'Where': '', 'Watch out for': '', 'Source': '' });
  for (const x of g.risky_steps) rows.push({ 'Step': '', 'Timestamp': '', 'What to do': String(x), 'Where': '', 'Watch out for': 'Irreversible or customer-visible', 'Source': 'Flagged in review' });
}

if (Array.isArray(g.quiz) && g.quiz.length) {
  rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'CHECK OF UNDERSTANDING', 'Where': '', 'Watch out for': '', 'Source': '' });
  for (let i = 0; i < g.quiz.length; i++) rows.push({ 'Step': '', 'Timestamp': '', 'What to do': 'Q' + (i + 1) + '. ' + (g.quiz[i].question || ''), 'Where': '', 'Watch out for': 'Expected: ' + (g.quiz[i].answer || ''), 'Source': 'Training check' });
}

return rows.map(function (r) { return { json: r }; });

parameters.text:
=Watch this recording again, but only around {{ $json.at }} (about {{ $json.tSec }} seconds in). Ignore the rest of the video.

Answer exactly this one question: {{ $json.ask }}

Reply with ONLY minified JSON, no prose and no code fences:
{"answered":true,"do":"the corrected action in the imperative, one sentence","where":"the app, screen or menu path visible at that moment","watch":"anything easy to get wrong here, or empty string","note":"if you still cannot make it out, say plainly what is obscuring it"}

Read what is actually on screen at that moment - field labels, button text, typed values. If it is genuinely still unreadable, set answered to false and use note to say why, for example the cursor covered it or the window scrolled too fast. Do not guess to be helpful: a wrong value in a procedure is worse than a gap someone knows to fill.
